import { useState, useEffect, useContext, useCallback } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import Confetti from 'react-confetti'
import { GameContext } from '../context/GameContext'
import { AuthContext } from '../context/AuthContext'
import { getQuestionsForStrand, getDifficultyColor } from '../data/questions'
import api from '../utils/api'

const STRAND_ICONS = { oral: '🎤', reading: '📖', writing: '✍️', grammar: '📝', literature: '📚' }
const STRAND_LABELS = { oral: 'Oral Language', reading: 'Reading', writing: 'Writing', grammar: 'Grammar', literature: 'Literature' }

export default function GameActivity() {
  const { strand, type, id } = useParams()
  const navigate = useNavigate()
  const { addPoints, wrongAnswer, feedback, clearFeedback, showConfetti, setShowConfetti } = useContext(GameContext)
  const { user } = useContext(AuthContext)

  const [questions, setQuestions] = useState([])
  const [currentIndex, setCurrentIndex] = useState(0)
  const [selectedAnswer, setSelectedAnswer] = useState(null)
  const [showResult, setShowResult] = useState(false)
  const [score, setScore] = useState(0)
  const [correctCount, setCorrectCount] = useState(0)
  const [answers, setAnswers] = useState([])
  const [startTime] = useState(Date.now())
  const [timeLeft, setTimeLeft] = useState(60)
  const [isComplete, setIsComplete] = useState(false)
  const [activityId, setActivityId] = useState(null)

  useEffect(() => {
    const qs = getQuestionsForStrand(strand, type, 5)
    setQuestions(qs.length > 0 ? qs : getQuestionsForStrand('integrated', 'final-challenge', 5))
  }, [strand, type])

  useEffect(() => {
    if (isComplete || questions.length === 0) return
    const timer = setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 1) {
          clearInterval(timer)
          handleTimeout()
          return 0
        }
        return prev - 1
      })
    }, 1000)
    return () => clearInterval(timer)
  }, [currentIndex, isComplete, questions.length])

  const currentQuestion = questions[currentIndex]
  const progress = questions.length > 0 ? ((currentIndex) / questions.length) * 100 : 0

  const handleTimeout = useCallback(() => {
    wrongAnswer('Time is up!')
    const newAnswers = [...answers, { question: currentIndex, correct: false, timedOut: true }]
    setAnswers(newAnswers)
    setShowResult(true)
    setTimeout(() => {
      if (currentIndex < questions.length - 1) {
        setCurrentIndex(prev => prev + 1)
        setSelectedAnswer(null)
        setShowResult(false)
        setTimeLeft(60)
      } else {
        finishQuiz(newAnswers)
      }
    }, 2000)
  }, [currentIndex, questions.length, answers, wrongAnswer])

  const handleAnswer = (answer) => {
    if (showResult || !currentQuestion) return
    setSelectedAnswer(answer)
    setShowResult(true)

    const isCorrect = answer === currentQuestion.correctAnswer
    const newAnswers = [...answers, { question: currentIndex, correct: isCorrect, answer, timedOut: false }]
    setAnswers(newAnswers)

    if (isCorrect) {
      setCorrectCount(prev => prev + 1)
      setScore(prev => prev + (currentQuestion.points || 10))
      addPoints(currentQuestion.points || 10, id)
    } else {
      wrongAnswer(currentQuestion.explanation)
    }

    setTimeout(() => {
      if (currentIndex < questions.length - 1) {
        setCurrentIndex(prev => prev + 1)
        setSelectedAnswer(null)
        setShowResult(false)
        setTimeLeft(60)
      } else {
        finishQuiz(newAnswers)
      }
    }, isCorrect ? 1500 : 2500)
  }

  const finishQuiz = async (finalAnswers) => {
    setIsComplete(true)
    const totalCorrect = finalAnswers.filter(a => a.correct).length
    const timeSpent = Math.floor((Date.now() - startTime) / 1000)

    try {
      const res = await api.post('/api/activities/quiz-submit', {
        strand,
        activityType: type || 'quiz',
        correctCount: totalCorrect,
        totalQuestions: questions.length,
        timeSpent,
        answers: finalAnswers.map(a => ({
          questionIndex: a.question,
          correct: a.correct,
          answer: a.answer || null
        }))
      })
      if (res.data?.accuracy >= 80) {
        setShowConfetti(true)
        setTimeout(() => setShowConfetti(false), 4000)
      }
    } catch (err) {
      console.error(err)
    }
  }

  const getAnswerClass = (option) => {
    if (!showResult) return selectedAnswer === option ? 'selected' : ''
    if (option === currentQuestion?.correctAnswer) return 'correct'
    if (selectedAnswer === option && option !== currentQuestion?.correctAnswer) return 'incorrect'
    return ''
  }

  if (isComplete) {
    const totalCorrect = answers.filter(a => a.correct).length
    const percentage = Math.round((totalCorrect / questions.length) * 100)
    const grade = percentage >= 80 ? 'A' : percentage >= 70 ? 'B' : percentage >= 60 ? 'C' : percentage >= 50 ? 'D' : 'F'

    return (
      <div className="game-activity animate-in">
        {showConfetti && <Confetti width={window.innerWidth} height={window.innerHeight} />}
        <div className="card" style={{textAlign:'center', padding:'48px'}}>
          <div style={{fontSize:'4rem', marginBottom:'16px'}}>
            {percentage >= 80 ? '🎉' : percentage >= 60 ? '👍' : '💪'}
          </div>
          <h2 style={{fontSize:'1.8rem', fontFamily:'var(--font-display)', marginBottom:'8px'}}>
            {percentage >= 80 ? 'Excellent!' : percentage >= 60 ? 'Good Job!' : 'Keep Practicing!'}
          </h2>
          <p style={{color:'var(--text-secondary)', marginBottom:'24px'}}>
            {STRAND_LABELS[strand]} - {type} challenge complete!
          </p>

          <div style={{display:'grid', gridTemplateColumns:'repeat(auto-fit, minmax(100px, 1fr))', gap:'16px', maxWidth:'400px', margin:'0 auto 24px'}}>
            <div className="stat-card" style={{textAlign:'center'}}>
              <div className="stat-content"><h4>{totalCorrect}/{questions.length}</h4><p>Correct</p></div>
            </div>
            <div className="stat-card" style={{textAlign:'center'}}>
              <div className="stat-content"><h4>{percentage}%</h4><p>Score</p></div>
            </div>
            <div className="stat-card" style={{textAlign:'center'}}>
              <div className="stat-content"><h4 style={{color: `var(--${grade === 'A' || grade === 'B' ? 'success' : grade === 'C' || grade === 'D' ? 'warning' : 'error'})`}}>{grade}</h4><p>Grade</p></div>
            </div>
          </div>

          <div style={{display:'flex', gap:'8px', justifyContent:'center', marginBottom:'24px'}}>
            {answers.map((a, i) => (
              <div key={i} className={`game-progress-dot ${a.correct ? 'correct' : 'incorrect'}`}>
                {i + 1}
              </div>
            ))}
          </div>

          {percentage >= 80 && <p style={{color:'var(--success)', fontWeight:600, marginBottom:'16px'}}>🏆 You earned bonus points for your great performance!</p>}

          <div className="flex gap-2" style={{justifyContent:'center'}}>
            <button className="btn btn-primary" onClick={() => {
              setCurrentIndex(0)
              setSelectedAnswer(null)
              setShowResult(false)
              setScore(0)
              setCorrectCount(0)
              setAnswers([])
              setIsComplete(false)
              setTimeLeft(60)
              const qs = getQuestionsForStrand(strand, type, 5)
              setQuestions(qs.length > 0 ? qs : getQuestionsForStrand('integrated', 'final-challenge', 5))
            }}>Play Again</button>
            <button className="btn btn-secondary" onClick={() => navigate('/dashboard')}>Back to Dashboard</button>
          </div>
        </div>
      </div>
    )
  }

  if (!currentQuestion) {
    return <div className="empty-state"><h3>Loading activity...</h3></div>
  }

  return (
    <div className="game-activity animate-in">
      {showConfetti && <Confetti width={window.innerWidth} height={window.innerHeight} />}

      <div className="game-header">
        <div>
          <h2>{STRAND_ICONS[strand]} {STRAND_LABELS[strand]}: {type}</h2>
          <p style={{color:'var(--text-secondary)', fontSize:'0.85rem'}}>Question {currentIndex + 1} of {questions.length}</p>
        </div>
        <div className="game-timer">
          <span>⏱️</span>
          <span style={{color: timeLeft < 10 ? 'var(--error)' : 'var(--primary)'}}>{timeLeft}s</span>
        </div>
      </div>

      <div className="game-progress">
        {questions.map((_, i) => (
          <div key={i} className={`game-progress-dot ${i < currentIndex ? (answers[i]?.correct ? 'correct' : 'incorrect') : i === currentIndex ? 'active' : ''}`}>
            {i + 1}
          </div>
        ))}
      </div>

      <div className="game-question">
        {currentQuestion.passage && (
          <div className="reading-passage" style={{marginBottom:'16px', maxHeight:'200px'}}>
            <p>{currentQuestion.passage}</p>
          </div>
        )}
        <h3>{currentQuestion.question}</h3>
        
        <div className="game-options">
          {currentQuestion.options?.map((option, i) => (
            <button
              key={i}
              className={`game-option ${getAnswerClass(option)}`}
              onClick={() => handleAnswer(option)}
              disabled={showResult}
            >
              {option}
            </button>
          ))}
        </div>
      </div>

      {feedback && (
        <div className={`game-feedback ${feedback.type}`}>
          <div>
            {feedback.type === 'correct' ? '✅' : '❌'}
          </div>
          <div>
            <h4>{feedback.message}</h4>
            {feedback.type === 'incorrect' && feedback.hint && (
              <p>{feedback.hint}</p>
            )}
            {feedback.type === 'incorrect' && currentQuestion?.explanation && (
              <p style={{marginTop:'4px', fontSize:'0.85rem'}}>{currentQuestion.explanation}</p>
            )}
          </div>
        </div>
      )}

      <div style={{display:'flex', justifyContent:'space-between', alignItems:'center', marginTop:'16px'}}>
        <p style={{fontSize:'0.85rem', color:'var(--text-secondary)'}}>
          Score: {score} XP | Correct: {correctCount}
        </p>
        <span className="badge-item" style={{padding:'4px 12px', fontSize:'0.75rem', background:'var(--bg)', borderRadius:'12px'}}>
          {currentQuestion.difficulty || 'medium'}
        </span>
      </div>
    </div>
  )
}
