import { Routes, Route, Navigate } from 'react-router-dom'
import { useContext } from 'react'
import { AuthContext } from './context/AuthContext'
import Navbar from './components/Navbar'
import Sidebar from './components/Sidebar'
import ProtectedRoute from './components/ProtectedRoute'
import Home from './pages/Home'
import Login from './pages/Login'
import Register from './pages/Register'
import Dashboard from './pages/Dashboard'
import Profile from './pages/Profile'
import Levels from './pages/Levels'
import OralLanguage from './pages/OralLanguage'
import Reading from './pages/Reading'
import Writing from './pages/Writing'
import Grammar from './pages/Grammar'
import Literature from './pages/Literature'
import Leaderboard from './pages/Leaderboard'
import TeacherDashboard from './pages/TeacherDashboard'
import Reports from './pages/Reports'
import SupportTools from './pages/SupportTools'
import GameActivity from './pages/GameActivity'

export default function App() {
  const { user, theme } = useContext(AuthContext)

  return (
    <div className={`app ${theme || 'light'}`}>
      {user && <Navbar />}
      <div className="main-layout">
        {user && <Sidebar />}
        <main className="main-content">
          <Routes>
            <Route path="/" element={user ? <Navigate to="/dashboard" /> : <Home />} />
            <Route path="/login" element={user ? <Navigate to="/dashboard" /> : <Login />} />
            <Route path="/register" element={user ? <Navigate to="/dashboard" /> : <Register />} />
            <Route path="/dashboard" element={<ProtectedRoute><Dashboard /></ProtectedRoute>} />
            <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
            <Route path="/levels" element={<ProtectedRoute><Levels /></ProtectedRoute>} />
            <Route path="/oral-language" element={<ProtectedRoute><OralLanguage /></ProtectedRoute>} />
            <Route path="/reading" element={<ProtectedRoute><Reading /></ProtectedRoute>} />
            <Route path="/writing" element={<ProtectedRoute><Writing /></ProtectedRoute>} />
            <Route path="/grammar" element={<ProtectedRoute><Grammar /></ProtectedRoute>} />
            <Route path="/literature" element={<ProtectedRoute><Literature /></ProtectedRoute>} />
            <Route path="/leaderboard" element={<ProtectedRoute><Leaderboard /></ProtectedRoute>} />
            <Route path="/teacher" element={<ProtectedRoute role="teacher"><TeacherDashboard /></ProtectedRoute>} />
            <Route path="/reports" element={<ProtectedRoute><Reports /></ProtectedRoute>} />
            <Route path="/support-tools" element={<ProtectedRoute><SupportTools /></ProtectedRoute>} />
            <Route path="/activity/:strand/:type/:id" element={<ProtectedRoute><GameActivity /></ProtectedRoute>} />
          </Routes>
        </main>
      </div>
    </div>
  )
}
