import { NavLink } from 'react-router-dom'
import { useContext } from 'react'
import { AuthContext } from '../context/AuthContext'

export default function Sidebar() {
  const { user } = useContext(AuthContext)

  const links = [
    { to: '/dashboard', label: 'Dashboard', icon: '📊', section: 'Main' },
    { to: '/levels', label: 'Game Levels', icon: '🎯', section: 'Game' },
    { to: '/oral-language', label: 'Oral Language', icon: '🎤', section: 'Strands' },
    { to: '/reading', label: 'Reading', icon: '📖', section: 'Strands' },
    { to: '/writing', label: 'Writing', icon: '✍️', section: 'Strands' },
    { to: '/grammar', label: 'Grammar', icon: '📝', section: 'Strands' },
    { to: '/literature', label: 'Literature', icon: '📚', section: 'Strands' },
    { to: '/leaderboard', label: 'Leaderboard', icon: '🏆', section: 'Community' },
    { to: '/support-tools', label: 'Support Tools', icon: '🔧', section: 'Tools' },
    { to: '/reports', label: 'Reports', icon: '📋', section: 'Tools' },
  ]

  if (user?.role === 'teacher' || user?.role === 'admin') {
    links.push({ to: '/teacher', label: 'Teacher Dashboard', icon: '👨‍🏫', section: 'Admin' })
  }

  const sections = [...new Set(links.map(l => l.section))]

  return (
    <aside className="sidebar" onClick={(e) => { if (window.innerWidth <= 768) e.currentTarget.classList.remove('open') }}>
      <nav className="sidebar-nav">
        {sections.map(section => (
          <div key={section} className="sidebar-section">
            <div className="sidebar-section-title">{section}</div>
            {links.filter(l => l.section === section).map(link => (
              <NavLink key={link.to} to={link.to} className={({isActive}) => `sidebar-link ${isActive ? 'active' : ''}`}>
                <span>{link.icon}</span>
                {link.label}
              </NavLink>
            ))}
          </div>
        ))}
      </nav>
    </aside>
  )
}
