import { createContext, useState, useCallback, useContext } from 'react'
import api from '../utils/api'
import { AuthContext } from './AuthContext'

export const GameContext = createContext()

export function GameProvider({ children }) {
  const { user, updateUser } = useContext(AuthContext)
  const [currentScore, setCurrentScore] = useState(0)
  const [streak, setStreak] = useState(0)
  const [xp, setXp] = useState(user?.xp || 0)
  const [coins, setCoins] = useState(user?.coins || 0)
  const [feedback, setFeedback] = useState(null)
  const [showConfetti, setShowConfetti] = useState(false)
  const [achievements, setAchievements] = useState([])

  const addPoints = useCallback(async (points, activityId) => {
    const speedBonus = Math.floor(Math.random() * 5)
    const totalPoints = points + speedBonus
    const newStreak = streak + 1
    const streakBonus = newStreak > 2 ? newStreak * 2 : 0
    const finalPoints = totalPoints + streakBonus

    setStreak(newStreak)
    setCurrentScore(prev => prev + finalPoints)
    setXp(prev => prev + finalPoints)
    setCoins(prev => prev + Math.floor(finalPoints / 5))

    setFeedback({
      type: 'correct',
      message: newStreak > 2 ? `Amazing! ${newStreak}x streak! +${finalPoints} XP` : `Correct! +${finalPoints} XP`,
      points: finalPoints,
      streak: newStreak
    })

    if (newStreak % 5 === 0) {
      setShowConfetti(true)
      setTimeout(() => setShowConfetti(false), 3000)
    }

    updateUser({ xp: (user?.xp || 0) + finalPoints, coins: (user?.coins || 0) + Math.floor(finalPoints / 5) })
  }, [streak, user, updateUser])

  const wrongAnswer = useCallback((hint) => {
    setStreak(0)
    setFeedback({
      type: 'incorrect',
      message: 'Not quite right!',
      hint: hint || 'Try again',
      points: 0
    })
  }, [])

  const clearFeedback = useCallback(() => {
    setFeedback(null)
  }, [])

  return (
    <GameContext.Provider value={{
      currentScore, setCurrentScore, streak, setStreak,
      xp, coins, feedback, showConfetti, achievements,
      addPoints, wrongAnswer, clearFeedback, setShowConfetti
    }}>
      {children}
    </GameContext.Provider>
  )
}
