export function getQuestionsForStrand(strand, type, count = 5) {
  const strandQuestions = QUESTIONS[strand]
  if (!strandQuestions) return []
  const typeQuestions = strandQuestions[type]
  if (!typeQuestions) return []
  const shuffled = [...typeQuestions].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, count)
}

export function getDifficultyColor(difficulty) {
  const colors = { easy: '#10b981', medium: '#f59e0b', hard: '#ef4444' }
  return colors[difficulty] || '#64748b'
}
