import { useState, useEffect } from 'react'

const DICTIONARY = {
  'benevolent': { meaning: 'Well-meaning, kind, and generous', example: 'The benevolent teacher helped every student.' },
  'ubiquitous': { meaning: 'Present or found everywhere', example: 'Smartphones have become ubiquitous in modern society.' },
  'eloquent': { meaning: 'Fluent or persuasive in speaking or writing', example: 'She gave an eloquent speech at the ceremony.' },
  'resilient': { meaning: 'Able to recover quickly from difficulties', example: 'Children are remarkably resilient.' },
  'ambiguous': { meaning: 'Open to more than one interpretation', example: 'His ambiguous answer left us confused.' },
  'empathy': { meaning: 'Ability to understand others\' feelings', example: 'A good leader shows empathy.' },
  'persevere': { meaning: 'Continue despite difficulties', example: 'She persevered through many challenges.' },
  'innovative': { meaning: 'Introducing new ideas or methods', example: 'The innovative design won an award.' },
  'collaborate': { meaning: 'Work together on a task', example: 'Teams must collaborate to succeed.' },
  'comprehend': { meaning: 'Grasp mentally; understand', example: 'It is difficult to comprehend the scale of the universe.' },
}

const GRAMMAR_RULES = [
  { title: 'Subject-Verb Agreement', rule: 'A singular subject takes a singular verb; a plural subject takes a plural verb.', example: 'She runs (singular). They run (plural).' },
  { title: 'Present Simple', rule: 'Used for habits, facts, and routines.', example: 'I eat breakfast every day.' },
  { title: 'Past Simple', rule: 'Used for completed actions in the past.', example: 'She visited Paris last year.' },
  { title: 'Future Simple', rule: 'Used for predictions and spontaneous decisions.', example: 'It will rain tomorrow.' },
  { title: 'Present Perfect', rule: 'Used for past actions with present relevance.', example: 'I have finished my homework.' },
  { title: 'Articles (a/an/the)', rule: 'Use "a" before consonant sounds, "an" before vowel sounds, "the" for specific items.', example: 'A dog, an apple, the moon.' },
  { title: 'Prepositions of Time', rule: 'Use "at" for specific times, "in" for months/years, "on" for days/dates.', example: 'At 5pm, in July, on Monday.' },
  { title: 'Active vs Passive Voice', rule: 'Active: subject performs action. Passive: subject receives action.', example: 'Active: The cat ate the fish. Passive: The fish was eaten by the cat.' },
]

const WRITING_TEMPLATES = [
  { title: 'Paragraph Structure', template: 'Topic Sentence → Supporting Detail 1 → Supporting Detail 2 → Supporting Detail 3 → Concluding Sentence' },
  { title: 'Essay Structure', template: 'Introduction (Hook + Thesis) → Body Paragraph 1 → Body Paragraph 2 → Body Paragraph 3 → Conclusion' },
  { title: 'Letter Format', template: 'Your Address → Date → Salutation → Body → Closing → Signature' },
  { title: 'Story Structure', template: 'Exposition → Rising Action → Climax → Falling Action → Resolution' },
]

export default function SupportTools() {
  const [activeTool, setActiveTool] = useState('dictionary')
  const [searchTerm, setSearchTerm] = useState('')
  const [dictResult, setDictResult] = useState(null)

  const searchDictionary = () => {
    if (!searchTerm.trim()) return
    const word = searchTerm.toLowerCase().trim()
    const result = DICTIONARY[word]
    if (result) {
      setDictResult({ word, ...result })
    } else {
      setDictResult({ word, meaning: 'Word not found in our dictionary', example: '' })
    }
  }

  const getSynonyms = (word) => {
    const syns = {
      'happy': ['joyful', 'elated', 'cheerful', 'delighted', 'merry'],
      'sad': ['unhappy', 'sorrowful', 'gloomy', 'melancholy', 'downcast'],
      'good': ['excellent', 'superb', 'outstanding', 'quality', 'fine'],
      'bad': ['terrible', 'awful', 'poor', 'inferior', 'dreadful'],
      'big': ['large', 'huge', 'enormous', 'massive', 'giant'],
      'small': ['tiny', 'little', 'miniature', 'compact', 'petite'],
    }
    return syns[word.toLowerCase()] || []
  }

  const tools = [
    { id: 'dictionary', label: 'Dictionary', icon: '📖' },
    { id: 'thesaurus', label: 'Thesaurus', icon: '📚' },
    { id: 'grammar', label: 'Grammar Guide', icon: '📝' },
    { id: 'templates', label: 'Writing Templates', icon: '✍️' },
  ]

  return (
    <div className="support-tools animate-in">
      <div className="page-header">
        <h2>🔧 English Support Tools</h2>
        <p>Dictionary, thesaurus, grammar guide, and writing templates</p>
      </div>

      <div className="teacher-tabs">
        {tools.map(t => (
          <button key={t.id} className={`teacher-tab ${activeTool === t.id ? 'active' : ''}`} onClick={() => setActiveTool(t.id)}>
            {t.icon} {t.label}
          </button>
        ))}
      </div>

      {activeTool === 'dictionary' && (
        <div className="tool-card">
          <h3>📖 Dictionary</h3>
          <div className="tool-search">
            <input placeholder="Search for a word..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} onKeyPress={e => e.key === 'Enter' && searchDictionary()} />
            <button className="btn btn-primary btn-sm" onClick={searchDictionary}>Search</button>
          </div>
          {dictResult && (
            <div className="tool-result">
              <h4 style={{textTransform:'capitalize', fontSize:'1.2rem'}}>{dictResult.word}</h4>
              <p style={{color:'var(--text)', marginBottom:'8px'}}>{dictResult.meaning}</p>
              {dictResult.example && <p style={{fontStyle:'italic', color:'var(--text-light)'}}>"{dictResult.example}"</p>}
            </div>
          )}
        </div>
      )}

      {activeTool === 'thesaurus' && (
        <div className="tool-card">
          <h3>📚 Thesaurus</h3>
          <div className="tool-search">
            <input placeholder="Find synonyms..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            <button className="btn btn-primary btn-sm" onClick={() => {
              const syns = getSynonyms(searchTerm)
              setDictResult(syns.length > 0 ? { word: searchTerm, synonyms: syns } : { word: searchTerm, synonyms: [], message: 'No synonyms found' })
            }}>Find</button>
          </div>
          {dictResult?.synonyms && (
            <div className="tool-result">
              <h4 style={{textTransform:'capitalize', marginBottom:'8px'}}>Synonyms for "{dictResult.word}"</h4>
              <div style={{display:'flex', flexWrap:'wrap', gap:'8px'}}>
                {dictResult.synonyms.map((s, i) => (
                  <span key={i} style={{padding:'6px 14px', background:'var(--primary)', color:'white', borderRadius:'20px', fontSize:'0.85rem'}}>{s}</span>
                ))}
              </div>
              {dictResult.synonyms.length === 0 && <p>{dictResult.message}</p>}
            </div>
          )}
        </div>
      )}

      {activeTool === 'grammar' && (
        <div className="tool-card">
          <h3>📝 Grammar Reference Guide</h3>
          <div style={{display:'grid', gap:'12px'}}>
            {GRAMMAR_RULES.map((rule, i) => (
              <div key={i} style={{background:'var(--bg)', padding:'16px', borderRadius:'var(--radius-sm)'}}>
                <h4 style={{fontSize:'0.95rem', marginBottom:'4px'}}>{rule.title}</h4>
                <p style={{fontSize:'0.85rem', color:'var(--text-secondary)'}}>{rule.rule}</p>
                <p style={{fontSize:'0.85rem', color:'var(--text-light)', fontStyle:'italic', marginTop:'4px'}}>e.g., {rule.example}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTool === 'templates' && (
        <div className="tool-card">
          <h3>✍️ Writing Templates</h3>
          <div style={{display:'grid', gap:'12px'}}>
            {WRITING_TEMPLATES.map((t, i) => (
              <div key={i} style={{background:'var(--bg)', padding:'16px', borderRadius:'var(--radius-sm)'}}>
                <h4 style={{fontSize:'0.95rem', marginBottom:'8px', color:'var(--primary)'}}>{t.title}</h4>
                <p style={{fontSize:'0.85rem', color:'var(--text-secondary)'}}>{t.template}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="card" style={{marginTop:'16px'}}>
        <h3 style={{marginBottom:'12px'}}>Vocabulary Bank</h3>
        <p style={{color:'var(--text-secondary)', marginBottom:'16px', fontSize:'0.9rem'}}>Essential English words for learners:</p>
        <div style={{display:'flex', flexWrap:'wrap', gap:'8px'}}>
          {Object.keys(DICTIONARY).map(word => (
            <span key={word} style={{padding:'6px 14px', background:'var(--bg)', borderRadius:'20px', fontSize:'0.85rem', border:'1px solid var(--border)', cursor:'pointer'}} 
                  onClick={() => { setSearchTerm(word); setActiveTool('dictionary'); setTimeout(() => setDictResult({ word, ...DICTIONARY[word] }), 100) }}>
              {word}
            </span>
          ))}
        </div>
      </div>
    </div>
  )
}
