export function calculateScore(correct, total) {
  if (total === 0) return 0
  return Math.round((correct / total) * 100)
}

export function getGrade(percentage) {
  if (percentage >= 80) return { letter: 'A', remark: 'Excellent performance!', color: '#10b981' }
  if (percentage >= 70) return { letter: 'B', remark: 'Very good!', color: '#3b82f6' }
  if (percentage >= 60) return { letter: 'C', remark: 'Good work!', color: '#f59e0b' }
  if (percentage >= 50) return { letter: 'D', remark: 'Fair effort', color: '#f97316' }
  if (percentage >= 40) return { letter: 'E', remark: 'Needs improvement', color: '#ef4444' }
  return { letter: 'F', remark: 'Keep trying!', color: '#dc2626' }
}

export function getLevelXp(level) {
  const levels = [0, 100, 250, 450, 700, 1000, 1400, 1900, 2500, 3200, 4200]
  return levels[level - 1] || 0
}

export function getLevelName(level) {
  const names = [
    'Basic Vocabulary and Oral Language',
    'Reading Skills Development',
    'Grammar Foundations',
    'Sentence Construction',
    'Paragraph Writing',
    'Advanced Grammar',
    'Literature Appreciation',
    'Creative Writing',
    'Critical Reading and Analysis',
    'Integrated English Challenge'
  ]
  return names[level - 1] || 'Master Level'
}
