import { useState, useEffect, useContext } from 'react'
import { AuthContext } from '../context/AuthContext'
import api from '../utils/api'

export default function Reports() {
  const { user } = useContext(AuthContext)
  const [report, setReport] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!user?.id) return
    api.get(`/api/reports/student/${user.id}`)
      .then(res => setReport(res.data.report))
      .catch(console.error)
      .finally(() => setLoading(false))
  }, [user?.id])

  const exportPDF = () => {
    window.print()
  }

  const exportExcel = () => {
    if (!report) return
    const csv = [
      ['English Quest - Student Report'],
      ['Student', report.studentName, 'Class', report.class, 'Date', report.date],
      [],
      ['Strand', 'Activities', 'Completed', 'Accuracy', 'Points', 'Time'],
      ...Object.entries(report.strands || {}).map(([strand, data]) => [
        strand, data.total, data.completed, `${data.accuracy}%`, data.points, `${Math.floor(data.time / 60)}m`
      ]),
      [],
      ['Total', report.totalActivities, report.completedActivities, `${report.percentage}%`, report.totalScore, ''],
      ['Grade', report.grade, '', '', '', ''],
      ['Remark', report.remark, '', '', '', '']
    ].map(row => row.join(',')).join('\n')

    const blob = new Blob([csv], { type: 'text/csv' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `${report.studentName.replace(/\s+/g, '_')}_report.csv`
    a.click()
  }

  if (loading) return <div className="empty-state"><h3>Loading report...</h3></div>
  if (!report) return <div className="empty-state"><h3>No report available</h3><p>Complete some activities first!</p></div>

  const gradeClass = report.grade === 'A' ? 'A' : report.grade === 'B' ? 'B' : report.grade === 'C' ? 'C' : report.grade === 'D' ? 'D' : report.grade === 'E' ? 'E' : 'F'

  return (
    <div className="animate-in" style={{maxWidth:'700px', margin:'0 auto'}}>
      <div className="page-header">
        <h2>📋 My Report</h2>
        <p>View your learning progress and performance summary</p>
      </div>

      <div className="report-card" id="report-card">
        <div className="report-header">
          <div>
            <h3>English Quest - Student Report</h3>
            <p style={{color:'var(--text-secondary)', fontSize:'0.85rem'}}>Date: {report.date}</p>
          </div>
          <div className={`report-grade ${gradeClass}`}>
            {report.grade}
          </div>
        </div>

        <div style={{display:'grid', gridTemplateColumns:'1fr 1fr', gap:'12px', marginBottom:'20px'}}>
          <div className="report-row"><span className="report-label">Student Name</span><span className="report-value">{report.studentName}</span></div>
          <div className="report-row"><span className="report-label">Student ID</span><span className="report-value">{report.studentId}</span></div>
          <div className="report-row"><span className="report-label">Class</span><span className="report-value">{report.class || 'N/A'}</span></div>
          <div className="report-row"><span className="report-label">Level</span><span className="report-value">{report.level}</span></div>
        </div>

        <h4 style={{marginBottom:'12px'}}>Performance by Strand</h4>
        {Object.entries(report.strands || {}).length === 0 ? (
          <p style={{color:'var(--text-secondary)'}}>No strand data available yet</p>
        ) : (
          Object.entries(report.strands || {}).map(([strand, data]) => (
            <div key={strand} style={{marginBottom:'12px'}}>
              <div style={{display:'flex', justifyContent:'space-between', fontSize:'0.9rem', marginBottom:'4px'}}>
                <span style={{fontWeight:600, textTransform:'capitalize'}}>{strand}</span>
                <span>{data.accuracy}% accuracy | {data.points} pts</span>
              </div>
              <div className="progress-bar">
                <div className="progress-fill" style={{width:`${data.accuracy}%`, background: data.accuracy >= 70 ? 'var(--success)' : data.accuracy >= 50 ? 'var(--warning)' : 'var(--error)'}}></div>
              </div>
            </div>
          ))
        )}

        <hr style={{border:'none', borderTop:'2px solid var(--border)', margin:'20px 0'}} />

        <div style={{display:'grid', gridTemplateColumns:'1fr 1fr', gap:'12px'}}>
          <div className="report-row"><span className="report-label">Total Activities</span><span className="report-value">{report.totalActivities}</span></div>
          <div className="report-row"><span className="report-label">Completed</span><span className="report-value">{report.completedActivities}</span></div>
          <div className="report-row"><span className="report-label">Total Score</span><span className="report-value">{report.totalScore} pts</span></div>
          <div className="report-row"><span className="report-label">Percentage</span><span className="report-value">{report.percentage}%</span></div>
          <div className="report-row"><span className="report-label">Grade</span><span className="report-value" style={{fontSize:'1.2rem'}}>{report.grade}</span></div>
          <div className="report-row"><span className="report-label">Remark</span><span className="report-value">{report.remark}</span></div>
        </div>

        <div style={{marginTop:'20px', display:'flex', gap:'8px', color:'var(--text-secondary)', fontSize:'0.8rem'}}>
          <span>⭐ {report.xp} XP</span>
          <span>| 🪙 {report.coins} Coins</span>
          <span>| ⭐ {report.stars} Stars</span>
        </div>
      </div>

      <div className="report-actions">
        <button className="btn btn-primary" onClick={exportPDF}>🖨️ Print Report</button>
        <button className="btn btn-secondary" onClick={exportExcel}>📊 Export CSV</button>
      </div>

      <div className="card" style={{marginTop:'24px'}}>
        <h3 style={{marginBottom:'12px'}}>Grading Scale</h3>
        <div style={{display:'grid', gridTemplateColumns:'repeat(auto-fit, minmax(100px, 1fr))', gap:'8px'}}>
          {[
            { grade: 'A', range: '80-100%', color: 'var(--success)' },
            { grade: 'B', range: '70-79%', color: 'var(--info)' },
            { grade: 'C', range: '60-69%', color: 'var(--warning)' },
            { grade: 'D', range: '50-59%', color: '#f97316' },
            { grade: 'E', range: '40-49%', color: 'var(--error)' },
            { grade: 'F', range: 'Below 40%', color: '#991b1b' },
          ].map(g => (
            <div key={g.grade} style={{textAlign:'center', padding:'12px', background:'var(--bg)', borderRadius:'var(--radius-sm)'}}>
              <div style={{fontSize:'1.5rem', fontWeight:800, color: g.color}}>{g.grade}</div>
              <div style={{fontSize:'0.8rem', color:'var(--text-secondary)'}}>{g.range}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}
