import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import api from '../utils/api'
import { LEVELS } from '../data/levels'

export default function Levels() {
  const navigate = useNavigate()
  const [levels, setLevels] = useState([])
  const [userXp, setUserXp] = useState(0)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    api.get('/api/levels')
      .then(res => {
        setLevels(res.data.levels || LEVELS.map((l, i) => ({
          ...l,
          isUnlocked: res.data.userXp >= l.minXp,
          isCompleted: res.data.currentLevel > l.id,
          isCurrent: res.data.currentLevel === l.id,
          progress: 0
        })))
        setUserXp(res.data.userXp)
      })
      .catch(() => setLevels(LEVELS.map(l => ({...l, isUnlocked: true, isCompleted: false, isCurrent: false, progress: 0}))))
      .finally(() => setLoading(false))
  }, [])

  const getStatusClass = (level) => {
    if (level.isCompleted) return 'completed'
    if (level.isCurrent) return 'current'
    if (!level.isUnlocked) return 'locked'
    return ''
  }

  return (
    <div className="levels-page animate-in">
      <div className="levels-header">
        <h2>Game Levels</h2>
        <p style={{color:'var(--text-secondary)'}}>Complete challenges to unlock the next level. You have {userXp} XP.</p>
      </div>

      <div className="levels-grid">
        {levels.map((level, index) => (
          <div key={level.id} className={`level-item ${getStatusClass(level)}`} onClick={() => level.isUnlocked && navigate(`/${level.strand === 'all' ? 'grammar' : level.strand}`)}>
            <div className={`level-number-badge ${level.isCompleted ? 'completed' : level.isUnlocked ? 'unlocked' : 'locked'}`}>
              {level.isCompleted ? '✓' : level.id}
            </div>
            <div className="level-info">
              <h3>Level {level.id}: {level.name}</h3>
              <p>{level.description}</p>
              {level.isCurrent && (
                <div className="progress-bar" style={{marginTop:'8px'}}>
                  <div className="progress-fill" style={{width:`${Math.min(100, level.progress || 0)}%`}}></div>
                </div>
              )}
            </div>
            <div className="level-xp">
              <div>{level.minXp} XP needed</div>
              {level.isCompleted && <div style={{color:'var(--success)'}}>✓ Completed</div>}
              {level.badgeName && <div style={{fontSize:'0.75rem'}}>🏅 {level.badgeName}</div>}
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}
