import { useState, useEffect, useContext } from 'react'
import { AuthContext } from '../context/AuthContext'
import api from '../utils/api'

export default function Leaderboard() {
  const { user } = useContext(AuthContext)
  const [leaderboard, setLeaderboard] = useState([])
  const [myRank, setMyRank] = useState(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    async function fetchData() {
      try {
        const [lbRes, rankRes] = await Promise.all([
          api.get('/api/leaderboard'),
          api.get('/api/leaderboard/my-rank')
        ])
        setLeaderboard(lbRes.data.leaderboard || [])
        setMyRank(rankRes.data)
      } catch (err) {
        console.error(err)
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [])

  const getAvatarColor = (name) => {
    const colors = ['#667eea', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#3b82f6']
    let hash = 0
    for (let i = 0; i < (name || '').length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash)
    return colors[Math.abs(hash) % colors.length]
  }

  const top3 = leaderboard.slice(0, 3)

  if (loading) return <div className="empty-state"><h3>Loading leaderboard...</h3></div>

  return (
    <div className="leaderboard-page animate-in">
      <div className="leaderboard-header">
        <h2>🏆 Leaderboard</h2>
        <p style={{color:'var(--text-secondary)'}}>Top English learners ranked by XP</p>
        {myRank && <p style={{fontSize:'0.9rem', marginTop:'8px'}}>Your rank: #{myRank.rank} of {myRank.total}</p>}
      </div>

      {top3.length > 0 && (
        <div className="leaderboard-podium">
          {top3[1] && (
            <div className="podium-item">
              <div className="podium-rank silver">2</div>
              <div className="podium-name">{top3[1].fullName || top3[1].username}</div>
              <div className="podium-score">{top3[1].xp} XP</div>
            </div>
          )}
          {top3[0] && (
            <div className="podium-item" style={{transform:'scale(1.15)'}}>
              <div className="podium-rank gold">1</div>
              <div className="podium-name" style={{fontWeight:700}}>{top3[0].fullName || top3[0].username}</div>
              <div className="podium-score">{top3[0].xp} XP</div>
            </div>
          )}
          {top3[2] && (
            <div className="podium-item">
              <div className="podium-rank bronze">3</div>
              <div className="podium-name">{top3[2].fullName || top3[2].username}</div>
              <div className="podium-score">{top3[2].xp} XP</div>
            </div>
          )}
        </div>
      )}

      <div className="leaderboard-list">
        {leaderboard.map((entry, index) => (
          <div key={entry.id} className={`leaderboard-row ${user?.id === entry.id ? 'current-user' : ''}`}>
            <div className={`lb-rank ${index < 3 ? 'top-3' : ''}`}>#{entry.rank}</div>
            <div className="lb-avatar" style={{background: getAvatarColor(entry.username)}}>
              {(entry.firstName?.[0] || entry.username?.[0] || '?').toUpperCase()}
            </div>
            <div className="lb-name">
              {entry.fullName || entry.username}
              {user?.id === entry.id && <span style={{fontSize:'0.75rem', color:'var(--primary)', marginLeft:'8px'}}>(You)</span>}
            </div>
            <div className="lb-class">{entry.class || '—'}</div>
            <div className="lb-level">Lvl {entry.current_level}</div>
            <div className="lb-xp">{entry.xp} XP</div>
          </div>
        ))}
        {leaderboard.length === 0 && (
          <div className="empty-state"><h3>No players yet</h3><p>Start playing to be the first on the leaderboard!</p></div>
        )}
      </div>
    </div>
  )
}
