import { useContext, useState } from 'react'
import { Link } from 'react-router-dom'
import { AuthContext } from '../context/AuthContext'
import { ThemeContext } from '../context/ThemeContext'
import { GameContext } from '../context/GameContext'

export default function Navbar() {
  const { user, logout } = useContext(AuthContext)
  const { darkMode, setDarkMode } = useContext(ThemeContext)
  const { xp, coins } = useContext(GameContext)
  const [showDropdown, setShowDropdown] = useState(false)

  return (
    <nav className="navbar">
      <div className="navbar-brand">
        <div className="logo-icon">EQ</div>
        <h1>English Quest</h1>
      </div>

      <div className="navbar-right">
        <div className="navbar-stats">
          <div className="navbar-stat">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>
            <span>{xp || user?.xp || 0}</span>
          </div>
          <div className="navbar-stat">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
            <span>{coins || user?.coins || 0}</span>
          </div>
        </div>

        <button className="mobile-menu-btn" onClick={() => document.querySelector('.sidebar')?.classList.toggle('open')}>
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="18" x2="21" y2="18"/></svg>
        </button>

        <button onClick={() => setDarkMode(!darkMode)} style={{background:'none', color:'white', fontSize:'1.2rem', padding:'4px'}}>
          {darkMode ? '☀️' : '🌙'}
        </button>

        <div className="navbar-user" onClick={() => setShowDropdown(!showDropdown)}>
          <div className="navbar-avatar">
            {(user?.firstName?.[0] || user?.username?.[0] || 'U').toUpperCase()}
          </div>
          <span className="navbar-username">{user?.firstName || user?.username}</span>
        </div>
      </div>

      {showDropdown && (
        <div style={{position:'absolute', top:'60px', right:'20px', background:'var(--bg-card)', borderRadius:'var(--radius)', boxShadow:'var(--shadow-lg)', border:'1px solid var(--border)', zIndex:1001, minWidth:'180px'}}>
          <Link to="/profile" style={{display:'block', padding:'12px 16px', color:'var(--text)', fontSize:'0.9rem'}} onClick={() => setShowDropdown(false)}>Profile</Link>
          <Link to="/reports" style={{display:'block', padding:'12px 16px', color:'var(--text)', fontSize:'0.9rem'}} onClick={() => setShowDropdown(false)}>My Reports</Link>
          <hr style={{border:'none', borderTop:'1px solid var(--border)'}}/>
          <button onClick={() => { logout(); setShowDropdown(false); }} style={{display:'block', width:'100%', padding:'12px 16px', background:'none', color:'var(--error)', fontSize:'0.9rem', textAlign:'left'}}>Logout</button>
        </div>
      )}
    </nav>
  )
}
