import { useState, useContext } from 'react'
import { Link } from 'react-router-dom'
import { AuthContext } from '../context/AuthContext'

export default function Login() {
  const { login } = useContext(AuthContext)
  const [form, setForm] = useState({ username: '', password: '' })
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)

  const handleSubmit = async (e) => {
    e.preventDefault()
    setError('')
    setLoading(true)
    try {
      await login(form.username, form.password)
    } catch (err) {
      setError(err.response?.data?.message || 'Login failed. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="auth-page">
      <div className="auth-card">
        <h2>Welcome Back!</h2>
        <p className="auth-subtitle">Continue your English learning journey</p>
        
        {error && <div style={{background:'var(--error-light)', color:'#991b1b', padding:'12px', borderRadius:'8px', marginBottom:'16px', fontSize:'0.9rem'}}>{error}</div>}
        
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Username or Email</label>
            <input type="text" value={form.username} onChange={e => setForm({...form, username: e.target.value})} placeholder="Enter your username" required />
          </div>
          <div className="form-group">
            <label>Password</label>
            <input type="password" value={form.password} onChange={e => setForm({...form, password: e.target.value})} placeholder="Enter your password" required />
          </div>
          <button type="submit" className="btn btn-primary" disabled={loading} style={{opacity: loading ? 0.7 : 1}}>
            {loading ? 'Logging in...' : 'Login'}
          </button>
        </form>
        
        <div className="auth-footer">
          <p>Don't have an account? <Link to="/register">Register here</Link></p>
          <p style={{marginTop:'8px', fontSize:'0.8rem', color:'var(--text-light)'}}>
            Demo accounts: admin/admin123 (teacher) or student/student123 (student)
          </p>
        </div>
      </div>
    </div>
  )
}
