import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import api from '../utils/api'

const ACTIVITIES = [
  { id: 'listening', title: 'Listening Comprehension', icon: '🎧', desc: 'Listen and answer questions', color: '#f59e0b', count: 5 },
  { id: 'pronunciation', title: 'Pronunciation Practice', icon: '🗣️', desc: 'Practice word pronunciation', color: '#f97316', count: 5 },
  { id: 'conversation', title: 'Conversation Skills', icon: '💬', desc: 'Complete dialogues and conversations', color: '#eab308', count: 5 },
]

export default function OralLanguage() {
  const navigate = useNavigate()
  const [progress, setProgress] = useState({})

  useEffect(() => {
    api.get('/api/progress/strand/oral').then(r => {
      const p = {}
      r.data.progress.forEach(item => { p[item.activity_id] = item })
      setProgress(p)
    }).catch(() => {})
  }, [])

  return (
    <div className="animate-in">
      <div className="page-header">
        <h2>🎤 Oral Language</h2>
        <p>Develop your speaking, listening, and pronunciation skills</p>
      </div>

      <div className="filter-bar">
        <select>
          <option>All Levels</option>
          <option>Level 1</option>
          <option>Level 2</option>
        </select>
        <select>
          <option>All Difficulties</option>
          <option>Easy</option>
          <option>Medium</option>
          <option>Hard</option>
        </select>
      </div>

      <div className="activities-grid">
        {ACTIVITIES.map(act => {
          const actProgress = progress[act.id] || {}
          return (
            <div key={act.id} className="activity-card" onClick={() => navigate(`/activity/oral/${act.id}/1`)}>
              <div className="activity-icon" style={{background:`${act.color}20`}}>{act.icon}</div>
              <h4>{act.title}</h4>
              <p>{act.desc}</p>
              <div className="activity-meta">
                <span>{act.count} questions</span>
                <span style={{color: actProgress.completed ? 'var(--success)' : 'var(--text-light)'}}>
                  {actProgress.completed ? '✓ Completed' : `${Math.round(actProgress.accuracy || 0)}%`}
                </span>
              </div>
            </div>
          )
        })}
      </div>

      <div className="card" style={{marginTop:'24px'}}>
        <h3 style={{marginBottom:'12px'}}>Quick Practice: Tongue Twisters</h3>
        <p style={{color:'var(--text-secondary)', marginBottom:'16px'}}>Practice these tongue twisters to improve your pronunciation:</p>
        <div style={{background:'var(--bg)', padding:'16px', borderRadius:'var(--radius-sm)', marginBottom:'8px'}}>
          <p style={{fontStyle:'italic'}}>"She sells seashells by the seashore."</p>
        </div>
        <div style={{background:'var(--bg)', padding:'16px', borderRadius:'var(--radius-sm)'}}>
          <p style={{fontStyle:'italic'}}>"Peter Piper picked a peck of pickled peppers."</p>
        </div>
      </div>
    </div>
  )
}
