import { useState, useEffect, useContext } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { AuthContext } from '../context/AuthContext'
import { GameContext } from '../context/GameContext'
import api from '../utils/api'
import { getLevelName } from '../utils/scoring'

const STRANDS = [
  { key: 'oral', label: 'Oral Language', icon: '🎤', color: '#f59e0b', path: '/oral-language' },
  { key: 'reading', label: 'Reading', icon: '📖', color: '#3b82f6', path: '/reading' },
  { key: 'writing', label: 'Writing', icon: '✍️', color: '#10b981', path: '/writing' },
  { key: 'grammar', label: 'Grammar', icon: '📝', color: '#8b5cf6', path: '/grammar' },
  { key: 'literature', label: 'Literature', icon: '📚', color: '#ec4899', path: '/literature' },
]

export default function Dashboard() {
  const { user } = useContext(AuthContext)
  const navigate = useNavigate()
  const [stats, setStats] = useState(null)
  const [challenges, setChallenges] = useState([])
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    async function fetchData() {
      try {
        const [statsRes, challengeRes] = await Promise.all([
          api.get('/api/progress/stats'),
          api.get('/api/challenges/daily')
        ])
        setStats(statsRes.data)
        setChallenges(challengeRes.data.challenges || [])
      } catch (err) {
        console.error('Dashboard fetch error:', err)
      } finally {
        setLoading(false)
      }
    }
    fetchData()
  }, [])

  if (loading) return <div className="empty-state"><h3>Loading dashboard...</h3></div>

  return (
    <div>
      <div className="dashboard-welcome animate-in">
        <h2>Welcome, {user?.firstName || user?.username}!</h2>
        <p>Continue your English language journey</p>
      </div>

      <div className="card-grid" style={{marginBottom:'24px'}}>
        <div className="stat-card">
          <div className="stat-icon primary">⭐</div>
          <div className="stat-content">
            <h4>{user?.xp || 0}</h4>
            <p>Total XP</p>
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-icon success">🏆</div>
          <div className="stat-content">
            <h4>{user?.currentLevel || 1}</h4>
            <p>Current Level</p>
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-icon warning">🎯</div>
          <div className="stat-content">
            <h4>{stats?.completedActivities || 0}</h4>
            <p>Activities Done</p>
          </div>
        </div>
        <div className="stat-card">
          <div className="stat-icon info">📊</div>
          <div className="stat-content">
            <h4>{stats?.avgAccuracy || 0}%</h4>
            <p>Avg Accuracy</p>
          </div>
        </div>
      </div>

      <div className="dashboard-grid">
        <div>
          <div className="dashboard-level-card" style={{marginBottom:'20px'}}>
            <h3>Current Level</h3>
            <div className="level-number">Level {user?.currentLevel || 1}</div>
            <div className="level-name">{getLevelName(user?.currentLevel || 1)}</div>
            <div className="level-progress">
              <div className="progress-bar">
                <div className="progress-fill" style={{width:`${Math.min(100, ((user?.xp || 0) % 1000) / 10)}%`}}></div>
              </div>
              <div className="progress-text">Next level: {1000 - ((user?.xp || 0) % 1000)} XP needed</div>
            </div>
          </div>

          <h3 style={{marginBottom:'16px'}}>Learning Strands</h3>
          <div className="card-grid">
            {STRANDS.map(s => (
              <div key={s.key} className={`strand-card ${s.key}`} onClick={() => navigate(s.path)}>
                <div className="strand-icon" style={{background:`${s.color}20`}}>{s.icon}</div>
                <h3>{s.label}</h3>
                <p>Practice and improve your {s.label.toLowerCase()} skills</p>
                <div className="strand-stats">
                  <span>{stats?.byStrand?.find(x => x.strand === s.key)?.completed || 0} completed</span>
                  <span>{Math.round(stats?.byStrand?.find(x => x.strand === s.key)?.avg_accuracy || 0)}% accuracy</span>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div>
          <div className="card" style={{marginBottom:'20px'}}>
            <div className="card-header">
              <h3>Daily Challenges</h3>
            </div>
            {challenges.length === 0 ? (
              <div className="empty-state" style={{padding:'24px 0'}}>
                <p>No challenges today. Check back later!</p>
              </div>
            ) : (
              challenges.map(c => (
                <div key={c.id} style={{padding:'12px 0', borderBottom:'1px solid var(--border)'}}>
                  <div style={{display:'flex', justifyContent:'space-between', alignItems:'center'}}>
                    <div>
                      <div style={{fontWeight:600, fontSize:'0.9rem'}}>{c.title}</div>
                      <div style={{fontSize:'0.8rem', color:'var(--text-secondary)'}}>{c.description}</div>
                    </div>
                    <div style={{textAlign:'right', fontSize:'0.8rem', color:'var(--accent)', fontWeight:600}}>
                      +{c.reward_xp} XP
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>

          <div className="card">
            <div className="card-header">
              <h3>Quick Links</h3>
            </div>
            <div style={{display:'flex', flexDirection:'column', gap:'8px'}}>
              <Link to="/levels" className="btn btn-secondary" style={{width:'100%'}}>View All Levels</Link>
              <Link to="/leaderboard" className="btn btn-secondary" style={{width:'100%'}}>Leaderboard</Link>
              <Link to="/support-tools" className="btn btn-secondary" style={{width:'100%'}}>Support Tools</Link>
              {user?.role === 'teacher' && (
                <Link to="/teacher" className="btn btn-primary" style={{width:'100%'}}>Teacher Dashboard</Link>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
